    use super::{CEILINGS, Role, Adopt, AdoptParts, ExistingProject, ExistingProjectParts, NewProject, NewProjectParts, SetUpProject, SetUp, SetUpParts, Return, ReturnParts, Request, Requesting, RequestingParts, SetUpRefusal, SetUpRefused, SetUpRefusedParts, Kind, Mode, SetUpStep, SettingUp, SettingUpParts, SetUpFailed, SetUpFailedParts, Connected, ConnectedParts, Stopped, StoppedParts, Connection, Offer, CreateStep, Made, MadeParts, CreateFailed, CreateFailedParts, FirstState, FirstRepository, FirstRepositoryParts, ForgeRow, ForgeRowParts, Forges, ForgesParts, Read, Reading, ReadingParts, DemoAnswer, DemoAnswerParts, ChangeSubject, ChangeSubjectParts, Watch, Watching, WatchingParts, Pull, PullParts, Queued, QueuedParts, GateReason, GateReasonParts, Reason, Repairing, RepairingParts, Landed, LandedParts, Step, Hold, Ci, GateKind, Verdict, Gate, GateParts, Used, UsedParts, ChangePanel, ChangePanelParts, Kinds, KindsParts, Rule, RuleParts, Protection, Adopted, AdoptedParts, CoreRefused, CoreRefusedParts, ForgeReason, ForgeRefused, ForgeRefusedParts, Outcome, Answer, AnswerParts, Path};
    use super::Limits;

    use alloc::boxed::Box;

    type Case = (&'static str, fn() -> bool);

    pub(super) fn table<const N: usize>(cases: &[Case; N]) {
        let mut failures = [None; N];
        let mut passed = true;
        for ((name, case), failure) in cases.iter().zip(&mut failures) {
            if !case() {
                *failure = Some(name);
                passed = false;
            }
        }
        assert!(passed, "{failures:?}");
    }

    pub(super) fn golden<T: PartialEq, E, D>(
        value: T,
        bytes: &[u8],
        encoded: Result<Box<[u8]>, E>,
        decoded: Result<T, D>,
    ) -> bool {
        let encoded = match encoded {
            Ok(encoded) => encoded.as_ref() == bytes,
            Err(_) => false,
        };
        let decoded = match decoded {
            Ok(decoded) => decoded == value,
            Err(_) => false,
        };
        encoded && decoded
    }

    type BoundDecode<T, L, P, R> = fn(&L, &[u8]) -> Result<T, (P, R)>;

    pub(super) fn bound<T, L, P: PartialEq, R: PartialEq>(
        label: (P, R),
        limits: &L,
        at: &[u8],
        past: &[u8],
        decode: BoundDecode<T, L, P, R>,
    ) -> bool {
        let (path, reason) = label;
        let at = decode(limits, at).is_ok();
        let past = match decode(limits, past) {
            Err((found_path, found_reason)) => found_path == path && found_reason == reason,
            Ok(_) => false,
        };
        at && past
    }
